/* minimizer, 2024. https://minimizer.art/ */
document.title = "Scribble Party - Generating..."

const append = (parent, xml) => {
 const t = document.createElement("template")
 t.innerHTML = xml
 const e = t.content.firstChild
 parent.append(e)
 return e
}

append(document.head, `<style>@keyframes spin { 0% {transform:rotate(0deg);} 100% {transform:rotate(360deg);}</style>`)

const loading = append(document.body, 
`<div style="display:flex;justify-content:center;align-items:center;height:100vh;margin:0;background-color:#fff;font-family:sans-serif;">
 <div style="text-align:center;">
  <h2>Generating...</h2>
  <div style="width:50px;height:50px;border:5px solid #fff;border-top:5px solid #000;border-radius:50%;animation:spin 1s linear infinite;margin:20px auto;"></div>
  <p style="color:#777;">Use 's' to save SVG once generated</p>
 </div>
</div>`)

const compressedArtCode = ''
const workerCode = `self.onmessage = async e => self.postMessage((await import('data:text/javascript;charset=utf-8,'+encodeURIComponent(await new Response(new Blob([Uint8Array.from(atob('${compressedArtCode}'), c => c.charCodeAt(0))]).stream().pipeThrough(new DecompressionStream('gzip'))).text()))).createOutput(e.data))`
const worker = new Worker(URL.createObjectURL(new Blob([workerCode], {type:'application/javascript'})))

const downloadSVG = (svg, filename) => {
 const url = URL.createObjectURL(new Blob([svg], {type:'image/svg+xml'}))
 const a = document.createElement('a')
 a.href = url
 a.download = filename
 document.body.appendChild(a)
 a.click()
 document.body.removeChild(a)
 URL.revokeObjectURL(url)
}

worker.onmessage = ({data:{name, svg}}) => {
 document.title = name
 document.body.removeChild(loading)
 append(document.body, svg)
 window.generatedSVG = svg
 document.addEventListener('keydown', e => e.code == 'KeyS' && downloadSVG(svg, name.replace('#','')+'.svg'))
}

